contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We will deposit `amount` from this contract into c, then call withdrawAll once.
    // After that, we call withdrawAll a second time and observe whether it sends any Ether.
    // The invariant: if the first withdrawAll succeeded (did not revert), then the second withdrawAll must not send any additional Ether to this contract.
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance for deposit");

        // Deposit amount to c
        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        // Record balance of this test contract before first withdraw
        uint balBeforeFirst = address(this).balance;

        // Perform first withdrawAll and record whether it reverted
        bool revertedFirst;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            revertedFirst = true;
        } else {
            revertedFirst = false;
        }

        // Record balance after first withdraw
        uint balAfterFirst = address(this).balance;

        // Perform second withdrawAll and record whether it reverted
        bool revertedSecond;
        c.withdrawAll(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            revertedSecond = true;
        } else {
            revertedSecond = false;
        }

        // Record balance after second withdraw
        uint balAfterSecond = address(this).balance;

        // If the first withdraw succeeded (did not revert), then the second withdraw must not increase this contract's balance.
        // In other words, balAfterSecond <= balAfterFirst when revertedFirst == false.
        assert(revertedFirst || balAfterSecond <= balAfterFirst);
    }

    // Allow the contract to receive Ether from c during withdrawAll
    receive() external payable {}
}

