// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        try c.deposit{value: amount}() {} catch { return; }
        uint balBeforeFirst = address(this).balance;
        bool revertedFirst;
        try c.withdrawAll() {
            revertedFirst = false;
        } catch {
            revertedFirst = true;
        }
        uint balAfterFirst = address(this).balance;
        bool revertedSecond;
        try c.withdrawAll() {
            revertedSecond = false;
        } catch {
            revertedSecond = true;
        }
        uint balAfterSecond = address(this).balance;
        assertTrue(revertedFirst || balAfterSecond <= balAfterFirst);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
